-- Whoever keeps or checks the books reads manual journals; an owner or an accountant writes
-- them. A member limited to some branches sees and writes only the journals of those branches.
CREATE POLICY manual_journals_select ON public.manual_journals FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor')
    AND ((SELECT app.tenant_branch_ids()) IS NULL OR branch_id = ANY ((SELECT app.tenant_branch_ids())::uuid[]))
  );
--> statement-breakpoint
