-- ── hand-written: what may happen to a manual journal ───────────────────────────────────────────
-- A draft changes freely and can be thrown away. It becomes posted only in the transaction that
-- posted its journal through the engine, with that journal's date, number and lines. A posted
-- one changes once more, to reversed, in the transaction that posted its reversal. Nothing else
-- about a posted or reversed manual journal ever changes, and it is never removed.
--
-- The functions run with the table owner's rights so that they can read the ledger whatever the
-- caller's branches, so they first refuse any row outside the caller's own company, asked afresh
-- for every row. Only a session signed in as postgres itself (a migration, or the removal of a
-- synthetic test company) is not held to these rules; the ledger's own triggers hold for
-- everyone. The times on a row are the database's own, never the caller's.
CREATE FUNCTION app.check_manual_journal() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.tenant_id IS DISTINCT FROM app.tenant_id() THEN
      RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'a posted manual journal is never removed; reverse it instead' USING ERRCODE = 'SE041';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  NEW.updated_at := now();
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := now();
    RETURN NEW;
  END IF;

  IF OLD.status = 'draft' AND NEW.status = 'draft' THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'draft' AND NEW.status = 'posted' THEN
    -- Posting changes nothing the journal was posted with.
    IF NEW.journal_date <> OLD.journal_date OR NEW.memo <> OLD.memo OR NEW.branch_id IS DISTINCT FROM OLD.branch_id THEN
      RAISE EXCEPTION 'a manual journal is posted as it stands' USING ERRCODE = 'SE043';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.journals j
      WHERE j.tenant_id = NEW.tenant_id AND j.id = NEW.journal_id
        AND j.source_type = 'manual_journal' AND j.source_id = NEW.id
        AND j.posted_txid = txid_current()
        AND j.journal_date = NEW.journal_date
        AND j.document_number IS NOT DISTINCT FROM NEW.number
        AND j.branch_id IS NOT DISTINCT FROM NEW.branch_id
    ) THEN
      RAISE EXCEPTION 'a manual journal is posted only with the journal the engine posted for it' USING ERRCODE = 'SE043';
    END IF;
    IF EXISTS (
      (SELECT l.line_no, l.account_id, l.debit, l.credit FROM public.manual_journal_lines l WHERE l.tenant_id = NEW.tenant_id AND l.manual_journal_id = NEW.id
       EXCEPT
       SELECT l.line_no, l.account_id, l.debit, l.credit FROM public.journal_lines l WHERE l.tenant_id = NEW.tenant_id AND l.journal_id = NEW.journal_id)
      UNION ALL
      (SELECT l.line_no, l.account_id, l.debit, l.credit FROM public.journal_lines l WHERE l.tenant_id = NEW.tenant_id AND l.journal_id = NEW.journal_id
       EXCEPT
       SELECT l.line_no, l.account_id, l.debit, l.credit FROM public.manual_journal_lines l WHERE l.tenant_id = NEW.tenant_id AND l.manual_journal_id = NEW.id)
    ) THEN
      RAISE EXCEPTION 'the journal posted is not the manual journal''s own lines' USING ERRCODE = 'SE043';
    END IF;
    NEW.posted_at := now();
    RETURN NEW;
  END IF;

  IF OLD.status = 'posted' AND NEW.status = 'reversed' THEN
    IF NEW.journal_date <> OLD.journal_date OR NEW.memo <> OLD.memo OR NEW.branch_id IS DISTINCT FROM OLD.branch_id
       OR NEW.number <> OLD.number OR NEW.journal_id <> OLD.journal_id OR NEW.posted_at <> OLD.posted_at OR NEW.posted_by <> OLD.posted_by THEN
      RAISE EXCEPTION 'a posted manual journal is never changed; reverse it instead' USING ERRCODE = 'SE041';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.journals j
      WHERE j.tenant_id = NEW.tenant_id AND j.id = NEW.reversal_journal_id
        AND j.reverses_journal_id = OLD.journal_id
        AND j.posted_txid = txid_current()
    ) THEN
      RAISE EXCEPTION 'a manual journal is reversed only with the reversal the engine posted for it' USING ERRCODE = 'SE043';
    END IF;
    NEW.reversed_at := now();
    RETURN NEW;
  END IF;

  IF OLD.status = 'draft' THEN
    RAISE EXCEPTION 'a draft is posted before it can be reversed' USING ERRCODE = 'SE043';
  END IF;
  RAISE EXCEPTION 'a posted manual journal is never changed; reverse it instead' USING ERRCODE = 'SE041';
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_manual_journal() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER manual_journals_check
  BEFORE INSERT OR UPDATE OR DELETE ON public.manual_journals
  FOR EACH ROW EXECUTE FUNCTION app.check_manual_journal();
--> statement-breakpoint
ALTER TABLE public.manual_journals ENABLE ALWAYS TRIGGER manual_journals_check;
--> statement-breakpoint

-- Lines are written and removed only while their journal is a draft. The journal's row is held
-- until the transaction ends, so a line cannot slip in while the journal is being posted.
CREATE FUNCTION app.check_manual_journal_line() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid;
  v_journal uuid;
  v_status text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_tenant := OLD.tenant_id;
    v_journal := OLD.manual_journal_id;
  ELSE
    v_tenant := NEW.tenant_id;
    v_journal := NEW.manual_journal_id;
  END IF;
  IF session_user <> 'postgres' THEN
    IF v_tenant IS DISTINCT FROM app.tenant_id() THEN
      RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
    END IF;
    SELECT m.status INTO v_status FROM public.manual_journals m
      WHERE m.tenant_id = v_tenant AND m.id = v_journal
      FOR SHARE;
    IF FOUND AND v_status <> 'draft' THEN
      RAISE EXCEPTION 'a posted manual journal is never changed; reverse it instead' USING ERRCODE = 'SE041';
    END IF;
    IF TG_OP = 'INSERT' THEN
      NEW.created_at := now();
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_manual_journal_line() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER manual_journal_lines_check
  BEFORE INSERT OR UPDATE OR DELETE ON public.manual_journal_lines
  FOR EACH ROW EXECUTE FUNCTION app.check_manual_journal_line();
--> statement-breakpoint
ALTER TABLE public.manual_journal_lines ENABLE ALWAYS TRIGGER manual_journal_lines_check;
--> statement-breakpoint

-- ── hand-written: the chart of accounts' own guard, tightened ───────────────────────────────────
-- app.check_account (drizzle/0011_accounts.sql) did nothing for a row outside the caller's
-- company and left that row to row-level security. A statement can change which company the
-- session is in between two of its rows, after the policies have read it, so the guard now
-- refuses such a row itself, asked afresh for every row. Only a session signed in as postgres
-- (a migration) is not held to it. Nothing else in the function changes.
CREATE OR REPLACE FUNCTION app.check_account() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_parent public.accounts%ROWTYPE;
  v_up uuid;
  v_depth integer := 1;
BEGIN
  IF session_user = 'postgres' THEN
    RETURN NEW;
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF TG_OP = 'UPDATE' THEN
    NEW.updated_at := now();
    IF OLD.archived_at IS NOT NULL AND NEW.archived_at IS NOT NULL THEN
      IF NEW.name IS DISTINCT FROM OLD.name OR NEW.code IS DISTINCT FROM OLD.code THEN
        RAISE EXCEPTION 'an archived account is not changed; restore it first' USING ERRCODE = 'SE035';
      END IF;
      NEW.archived_at := OLD.archived_at;
    ELSIF OLD.archived_at IS NULL AND NEW.archived_at IS NOT NULL THEN
      NEW.archived_at := now();
      IF NEW.is_group AND EXISTS (
        SELECT 1 FROM public.accounts c
        WHERE c.tenant_id = NEW.tenant_id AND c.parent_id = NEW.id AND c.archived_at IS NULL
      ) THEN
        RAISE EXCEPTION 'a heading is archived only when everything under it is' USING ERRCODE = 'SE036';
      END IF;
    ELSIF OLD.archived_at IS NOT NULL AND NEW.archived_at IS NULL AND NEW.parent_id IS NOT NULL THEN
      SELECT a.* INTO v_parent FROM public.accounts a
        WHERE a.tenant_id = NEW.tenant_id AND a.id = NEW.parent_id
        FOR SHARE;
      IF v_parent.archived_at IS NOT NULL THEN
        RAISE EXCEPTION 'an account is restored only under a heading that is not archived' USING ERRCODE = 'SE032';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  NEW.created_at := now();
  NEW.updated_at := now();
  IF NEW.parent_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT a.* INTO v_parent FROM public.accounts a
    WHERE a.tenant_id = NEW.tenant_id AND a.id = NEW.parent_id
    FOR SHARE;
  IF NOT FOUND THEN
    -- Left for the foreign key to refuse.
    RETURN NEW;
  END IF;
  IF NOT v_parent.is_group THEN
    RAISE EXCEPTION 'an account can sit only under a heading' USING ERRCODE = 'SE031';
  END IF;
  IF v_parent.archived_at IS NOT NULL THEN
    RAISE EXCEPTION 'an account cannot sit under an archived heading' USING ERRCODE = 'SE032';
  END IF;
  IF NOT NEW.is_control THEN
    IF NEW.control_type IS DISTINCT FROM (CASE WHEN v_parent.control_type IN ('bank', 'cash') THEN v_parent.control_type END) THEN
      RAISE EXCEPTION 'an account takes what it is for from its heading' USING ERRCODE = 'SE033';
    END IF;
    v_up := v_parent.parent_id;
    WHILE v_up IS NOT NULL LOOP
      v_depth := v_depth + 1;
      SELECT a.parent_id INTO v_up FROM public.accounts a WHERE a.tenant_id = NEW.tenant_id AND a.id = v_up;
    END LOOP;
    IF v_depth > 5 OR (NEW.is_group AND v_depth > 4) THEN
      RAISE EXCEPTION 'accounts can be at most five levels below a root, and headings four' USING ERRCODE = 'SE034';
    END IF;
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
ALTER TABLE public.accounts ENABLE ALWAYS TRIGGER accounts_check;
